    "What is BuyWise AI?": "BuyWise AI શું છે?",
    "How does SmartCompare work?": "SmartCompare કેવી રીતે કામ કરે છે?",
    "What does VERIFIED TODAY mean on coupons?": "કૂપન્સ પર \"આજે જ ચકાસાયેલ\" (VERIFIED TODAY) નો અર્થ શું છે?",
    "How do I create a Price Alert?": "કિંમત ચેતવણી (Price Alert) કેવી રીતે બનાવવી?",
    "How does AI Virtual Try-On work and are my photos safe?": "AI વર્ચ્યુઅલ ટ્રાય-ઓન કેવી રીતે કામ કરે છે અને શું મારા ફોટા સુરક્ષિત છે?",
    "Does BuyWise charge extra when I buy through Amazon links?": "શું એમેઝોન લિંક્સ દ્વારા ખરીદી કરવાથી BuyWise વધારાનો ચાર્જ લે છે?",
    "What is BuyWise Partners Marketplace?": "BuyWise પાર્ટનર્સ માર્કેટપ્લેસ શું છે?",
    "How do I delete my BuyWise account?": "હું મારું BuyWise એકાઉન્ટ કેવી રીતે કાઢી નાખું?",
    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI એ \"શોધ → સરખામણી → ટ્રાય-ઓન → ખરીદી\" મોડેલ પર કાર્યરત AI-સંચાલિત શોપિંગ ઇન્ટેલિજન્સ પ્લેટફોર્મ છે. તે એમેઝોન ઇન્ડિયા, ફ્લિપકાર્ટ, મિંત્રા, નાયકા અને અજીઓ પર લાઇવ કિંમતોની સરખામણી કરે છે, કિંમતમાં ઘટાડો ટ્રેક કરે છે, કૂપન્સ ચકાસે છે અને AI વર્ચ્યુઅલ ટ્રાય-ઓન પ્રદાન કરે છે.",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare લાઈવ વેપારી કિંમતો મેળવે છે, ઇન્સ્ટન્ટ બેંક/ક્રેડિટ કાર્ડ ડિસ્કાઉન્ટ ગણે છે અને ઉત્પાદન માટે સાચી અસરકારક કિંમત નક્કી કરવા ચકાસાયેલ કૂપન્સ ઉમેરે છે.",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"આજે જ ચકાસાયેલ\" નો અર્થ એ છે કે કૂપન કોડ આજે જ સક્રિય ડેટા સામે ચકાસવામાં આવ્યો હતો. માત્ર આજે જ ચકાસાયેલ સક્રિય કૂપન્સ બાદ કરવામાં આવે છે.",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "કોઈપણ ઉત્પાદન શોધો અને \"કિંમત ચેતવણી બનાવો\" પર ક્લિક કરો. તમારી લક્ષ્ય કિંમત સેટ કરો, અને કિંમત ઘટે ત્યારે BuyWise તમને સૂચના આપશે.",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI વર્ચ્યુઅલ ટ્રાય-ઓન (VTO) તમારા અપલોડ કરેલા ફોટા પર કપડાં અને દાગીના બતાવવા માટે અદ્યતન એલ્ગોરિધમ્સનો ઉપયોગ કરે છે. તમારા ફોટા ખાનગી, એન્ક્રિપ્ટેડ અને સુરક્ષિત છે.",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "ના! એમેઝોન ઇન્ડિયા અથવા પાર્ટનર લિંક્સ દ્વારા ખરીદી કરવા પર કિંમત બિલકુલ સમાન રહે છે. BuyWise યોગ્ય ખરીદીઓ પર એફિલિએટ કમિશન મેળવી શકે છે.",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise પાર્ટનર્સ ચકાસાયેલ સ્વતંત્ર વેપારીઓ અને સ્થાનિક વેચાણકર્તાઓને અસલી ઉત્પાદનો (જેમ કે કાંજીવરમ સિલ્ક સાડીઓ અને કુંદન જ્વેલરી) બાયવાઇઝ પર વેચવાની મંજૂરી આપે છે.",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "તમે પ્રોફાઇલ → એકાઉન્ટ કાઢી નાખો માંથી કોઈપણ સમયે તમારું એકાઉન્ટ કાઢી નાખી શકો છો. તમારો ડેટા, એલર્ટ્સ અને ટ્રાય-ઓન ફોટા કાયમી ધોરણે કાઢી નાખવામાં આવશે.",
