    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI \"खोजें → तुलना करें → ट्राई करें → खरीदें\" मॉडल पर आधारित AI-संचालित शॉपिंग इंटेलिजेंस प्लेटफॉर्म है। यह लाइव कीमतों की तुलना करता है और AI ट्राई-ऑन प्रदान करता है।",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare लाइव मर्चेंट कीमतों को चेक करता है, बैंक डिस्काउंट की गणना करता है और उत्पाद की सही प्रभावी कीमत (Effective Price) बताता है।",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"आज ही सत्यापित\" का अर्थ है कि कूपन कोड आज सक्रिय डेटा के साथ चेक किया गया है। केवल सत्यापित कूपन ही छूट में जोड़े जाते हैं।",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "किसी भी उत्पाद को खोजें और \"मूल्य अलर्ट बनाएं\" पर क्लिक करें। अपनी लक्षित कीमत सेट करें, कीमत घटने पर BuyWise आपको तुरंत सूचित करेगा।",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI वर्चुअल ट्राई-ऑन (VTO) आपकी फोटो पर कपड़े और आभूषण का दृश्य पूर्वावलोकन प्रदान करता है। आपकी तस्वीरें पूरी तरह से निजी और सुरक्षित हैं।",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "नहीं! अमेज़न इंडिया या एफिलिएट लिंक से खरीदारी करने पर आपको वही समान कीमत चुकानी होती है। BuyWise को कमीशन मिल सकता है।",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise पार्टनर्स सत्यापित स्वतंत्र विक्रेताओं को प्रामाणिक उत्पाद (जैसे कांजीवरम सिल्क साड़ी और कुंदन आभूषण) सीधे BuyWise पर बेचने की अनुमति देता है।",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "आप प्रोफ़ाइल → अकाउंट हटाएं से किसी भी समय अपना अकाउंट हटा सकते हैं। आपकी प्राथमिकताएं, अलर्ट और ट्राई-ऑन फोटो हमेशा के लिए हटा दिए जाएंगे।",
