    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI ek AI-powered shopping platform hai jo Search → Compare → Try → Buy par kaam karta hai. Ye live prices compare karta hai aur AI Try-On deta hai.",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare live merchant prices check karta hai, bank discounts calculate karta hai aur verified coupons add karke true Effective Price dikhati hai.",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "VERIFIED TODAY ka matlab hai ki coupon code aaj active merchant data se verify kiya gaya hai. Sirf verified coupons hi final price se deduct hote hain.",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "Kisi bhi product ko search karein aur Create Price Alert par click karein. Price drop hone par BuyWise aapko instant notify karega.",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI Virtual Try-On (VTO) aapki photo par clothes aur jewellery try karke dikhati hai. Aapki photos 100% private, encrypted aur safe rehti hain.",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "Nahi! Amazon ya store links se buy karne par price bilkul same rehti hai. BuyWise ko chhota affiliate commission milta hai.",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise Partners verified independent sellers ko authentic products (jaise Kanjivaram silk sarees aur Kundan jewellery) directly BuyWise par sell karne ki permission deta hai.",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "Aap Profile → Delete Account se kisi bhi time apna account delete kar sakte hain. Aapka all data permanently delete ho jayega.",
