    "Discover how BuyWise AI queries real-time merchant APIs, verifies bank offers, and calculates effective prices.": "BuyWise AI কীভাবে রিয়েল-টাইম এপিআই পরীক্ষা করে এবং কার্যকর দাম নির্ধারণ করে তা জানুন।",
    "Learn how your uploaded model photographs are encrypted, processed, and protected during AI Try-On sessions.": "AI ট্রাই-অন সেশনের সময় আপনার আপলোড করা ছবিগুলি কীভাবে এনক্রিপ্ট ও সুরক্ষিত থাকে তা জানুন।",
    "An overview of consumer rights under Indian e-commerce laws regarding returns, price transparency, and grievance redressal.": "ফেরত, দামের স্বচ্ছতা এবং অভিযোগ প্রতিকার সম্পর্কিত ভারতীয় ই-কমার্স আইনের অধীনে অধিকারসমূহ।",
    "Detailed breakdown of the 5 best laptops under ₹80,000 in India including MacBook Air M2, ASUS OLED, HP Pavilion, Lenovo Ultra 5, and Dell Inspiron.": "MacBook Air M2, ASUS OLED সহ ভারতে ₹80,000 এর নিচে ৫টি সেরা ল্যাপটপের বিবরণ।",
    "Looking to buy the new iPhone 17 in India? We compared live prices on Amazon India, Flipkart, and Croma to reveal the lowest deal starting at ₹82,900.": "ভারতে নতুন iPhone 17 কিনতে চান? আমরা অ্যামাজন ও ফ্লিপকার্টে লাইভ দাম তুলনা করেছি।",
    "We compared noise cancellation, sound clarity, battery endurance, and current Indian deals for Sony WH-1000XM5.": "আমরা Sony WH-1000XM5 এর সাউন্ড কোয়ালিটি এবং ব্যাটারি লাইফের তুলনা করেছি।",
