    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI হলো \"অনুসন্ধান → তুলনা → ট্রাই-অন → কেনাকাটা\" মডেলে পরিচালিত একটি AI শপিং প্ল্যাটফর্ম। এটি অ্যামাজন, ফ্লিপকার্ট, মিন্ট্রা ও নাইকার লাইভ দাম তুলনা করে।",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare লাইভ বিক্রেতার দাম পরীক্ষা করে, ব্যাংক ডিসকাউন্ট হিসাব করে এবং প্রকৃত দাম প্রদর্শন করে।",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"আজই যাচাইকৃত\" মানে কুপন কোডটি আজ পরীক্ষা করা হয়েছে। শুধুমাত্র যাচাইকৃত কুপনই ছাড়ে প্রযোজ্য।",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "যেকোনো পণ্য খুঁজুন এবং \"মূল্য সতর্কতা তৈরি করুন\" এ ক্লিক করুন। দাম কমলে BuyWise আপনাকে তাৎক্ষণিক নোটিফিকেশন পাঠাবে।",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI ভার্চুয়াল ট্রাই-অন (VTO) আপনার আপলোড করা ছবিতে পোশাক ও গয়না পরা চেহারা দেখায়। আপনার ছবি সম্পূর্ণ ব্যক্তিগত ও সুরক্ষিত।",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "না! অ্যামাজন বা অফিশিয়াল লিঙ্কের মাধ্যমে কেনাকাটায় দাম একেবারেই সমান থাকে। BuyWise কমিশন পেতে পারে।",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise পার্টনার্স খাঁটি পণ্য (যেমন কাঞ্জিভরম সিল্ক শাড়ি ও কুন্দন গয়না) সরাসরি বিক্রি করার সুযোগ দেয়।",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "আপনি প্রোফাইল → অ্যাকাউন্ট মুছুন থেকে যেকোনো সময় অ্যাকাউন্ট মুছে ফেলতে পারেন। আপনার সমস্ত ডেটা স্থায়ীভাবে মুছে ফেলা হবে।",
