    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI हे \"शोधा → तुलना करा → ट्राय करा → खरेदी करा\" मॉडेलवर काम करणारे AI प्लॅटफॉर्म आहे। हे अ‍ॅमेझॉन आणि फ्लिपकार्टवर थेट किमतींची तुलना करते।",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare लाइव्ह किमती तपासते, बँक सवलत मोजते आणि उत्पादनाची खरी प्रभावी किंमत दाखवते।",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"आजच सत्यापित\" म्हणजे कूपन कोड आजच तपासला गेला आहे। फक्त सत्यापित कूपन अंतिम किमतीतून कमी केले जातात।",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "कोणतेही उत्पादन शोधा आणि \"किंमत अलर्ट तयार करा\" वर क्लिक करा। किंमत कमी झाल्यावर BuyWise तुम्हाला त्वरित सूचित करेल।",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI व्हर्च्युअल ट्राय-ऑन (VTO) तुमच्या फोटोवर कपडे आणि दागिने ट्राय करून दाखवते। तुमचे फोटो १००% सुरक्षित आहेत।",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "नाही! अ‍ॅमेझॉन किंवा पार्टनर लिंकवरून खरेदी केल्यास किंमत तीच राहते। BuyWise ला एफिलिएट कमिशन मिळू शकते।",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise पार्टनर्स विक्रेत्यांना अस्सल उत्पादने (जसे की कांजीवरम सिल्क साड्या आणि कुंदन दागिने) थेट विकण्याची अनुमती देते।",
