    "How does AI Virtual Try-On work and are my photos safe?": "AI వర్చువల్ ట్రై-ఆన్ ఎలా పనిచేస్తుంది మరియు నా ఫోటోలు సురక్షితంగా ఉన్నాయా?",
    "Does BuyWise charge extra when I buy through Amazon links?": "అమెజాన్ లింక్‌ల ద్వారా కొనుగోలు చేసినప్పుడు BuyWise అదనపు రుసుము వసూలు చేస్తుందా?",
    "What is BuyWise Partners Marketplace?": "BuyWise పార్ట్‌నర్స్ మార్కెట్‌ప్లేస్ అంటే ఏమిటి?",
    "How do I delete my BuyWise account?": "నేను నా BuyWise ఖాతాను ఎలా తొలగించాలి?",
    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI అనేది \"వెతకండి → పోల్చండి → ట్రై చేయండి → కొనండి\" ప్రాతిపదికన పనిచేసే AI షాపింగ్ ప్లాట్‌ఫారమ్.",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare ప్రత్యక్ష ధరలను తనిఖీ చేస్తుంది, బ్యాంక్ డిస్కౌంట్లను లెక్కిస్తుంది మరియు నిజమైన ధరకు వర్తించే కూపన్లను జోడిస్తుంది.",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"ఈరోజే సరిచూడబడింది\" అంటే కూపన్ కోడ్ ఈరోజే తనిఖీ చేయబడింది. నిజమైన కూపన్లు మాత్రమే తుది ధర నుండి తగ్గించబడతాయి.",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "ఏదైనా ఉత్పత్తిని వెతికి \"ధర హెచ్చరికను సృష్టించండి\"పై క్లిక్ చేయండి. ధర తగ్గినప్పుడు BuyWise మీకు నోటిఫికేషన్ పంపుతుంది.",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI వర్చువల్ ట్రై-ఆన్ (VTO) మీ ఫోటోపై దుస్తులు మరియు ఆభరణాలను ట్రై చేయడానికి సహాయపడుతుంది. మీ ఫోటోలు సురక్షితం.",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "లేదు! అమెజాన్ లేదా భాగస్వామ్య లింక్‌ల ద్వారా కొనుగోలు చేసినప్పుడు ధర ఖచ్చితంగా అదే విధంగా ఉంటుంది.",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise పార్ట్‌నర్స్ నిజమైన ఉత్పత్తులను (కంజీవరం పట్టు చీరలు, కుందన్ ఆభరణాలు) నేరుగా విక్రయించడానికి అనుమతిస్తుంది.",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "మీరు ప్రొఫైల్ → ఖాతాను తొలగించండి నుండి ఎప్పుడైనా మీ ఖాతాను తొలగించవచ్చు. మీ డేటా శాశ్వతంగా తొలగించబడుతుంది.",
