    "BuyWise Editorial Team": "BuyWise எடிட்டோரியல் குழு",
    "BuyWise AI Privacy Team": "BuyWise AI தனியுரிமை குழு",
    "BuyWise Editorial": "BuyWise எடிட்டோரியல்",
    "BuyWise AI Shopping Engine": "BuyWise AI ஷாப்பிங் எஞ்சின்",
    "What is BuyWise AI?": "BuyWise AI என்றால் என்ன?",
    "How does SmartCompare work?": "SmartCompare எவ்வாறு செயல்படுகிறது?",
    "What does VERIFIED TODAY mean on coupons?": "கூப்பன்களில் \"இன்றே சரிபார்க்கப்பட்டது\" (VERIFIED TODAY) என்பதன் பொருள் என்ன?",
    "How do I create a Price Alert?": "விலை விழிப்பூட்டலை (Price Alert) எவ்வாறு உருவாக்குவது?",
    "How does AI Virtual Try-On work and are my photos safe?": "AI விர்ச்சுவல் டிரை-ஆன் எவ்வாறு செயல்படுகிறது மற்றும் எனது புகைப்படங்கள் பாதுகாப்பானவையா?",
    "Does BuyWise charge extra when I buy through Amazon links?": "அமேசான் லிங்க் மூலம் வாங்கும்போது BuyWise கூடுதல் கட்டணம் வசூலிக்கிறதா?",
    "What is BuyWise Partners Marketplace?": "BuyWise பார்ட்னர்ஸ் மார்க்கெட்பிளேஸ் என்றால் என்ன?",
    "How do I delete my BuyWise account?": "எனது BuyWise கணக்கை எவ்வாறு நீக்குவது?",
    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI என்பது \"தேடு → ஒப்பிடு → டிரை செய் → வாங்கு\" மாதிரியில் இயங்கும் AI ஷாப்பிங் தளமாகும்.",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare நேரலை விலைகளை சரிபார்த்து, வங்கி தள்ளுபடிகளைக் கணக்கிட்டு உண்மையான பயனுள்ள விலையைக் காட்டுகிறது.",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"இன்றே சரிபார்க்கப்பட்டது\" என்பது கூப்பன் கோட் இன்றே சரிபார்க்கப்பட்டது என்பதைக் குறிக்கிறது. செல்லுபடியாகும் கூப்பன்கள் மட்டுமே சேர்க்கப்படும்.",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "எந்தவொரு பொருளையும் தேடி \"விலை விழிப்பூட்டலை உருவாக்கு\" என்பதைக் கிளிக் செய்யவும். விலை குறையும் போது BuyWise உங்களுக்கு அறிவிக்கும்.",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI விர்ச்சுவல் டிரை-ஆன் (VTO) உங்கள் புகைப்படத்தில் ஆடைகள் மற்றும் நகைகளை அணிந்து பார்க்க உதவுகிறது. உங்கள் புகைப்படங்கள் பாதுகாப்பானவை.",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "இல்லை! அமேசான் அல்லது பார்ட்னர் லிங்க் மூலம் வாங்கும்போது அதே விலையே இருக்கும்.",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise பார்ட்னர்ஸ் சரிபார்க்கப்பட்ட விற்பனையாளர்களை உண்மையான பொருட்களை (காஞ்சிபுரம் பட்டுப் புடவைகள், குந்தன் நகைகள்) நேரடியாக விற்க அனுமதிக்கிறது.",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "சுயவிவரம் → கணக்கை நீக்கு என்பதிலிருந்து எப்போது வேண்டுமானாலும் உங்கள் கணக்கை நீக்கலாம். உங்களின் அனைத்துத் தரவுகளும் நீக்கப்படும்.",
