    "Shop authentic handpicked products directly from verified partner brands. Enjoy AI Virtual Try-On, guaranteed stock, direct partner packing, fast delivery & dedicated customer support.": "சரிபார்க்கப்பட்ட பார்ட்னர் பிராண்டுகளிலிருந்து நேரடியாகப் பொருட்களை வாங்குங்கள். AI விர்ச்சுவல் ட்ரை-ஆன் மற்றும் வேகமான டெலிவரியை அனுபவியுங்கள்.",
