    "Your Identity, Body & Pose Preserved ✨": "உங்கள் அடையாளம், உடல் வடிவம் மற்றும் தோற்றம் பாதுகாக்கப்பட்டது ✨",
    "Upload Your Photo for AI Try-On": "AI ட்ரை-ஆனிற்கு உங்கள் புகைப்படத்தைப் பதிவேற்றவும்",
    "Base photo active. Search any saree, gown, suit, or jewellery below to virtually try on!": "புகைப்படம் தயாராக உள்ளது. எந்த சேலை, கவுன், சூட் அல்லது நகைகளையும் ட்ரை செய்து பாருங்கள்!",
