    "Your photo is used solely for generating your private virtual try-on preview. We respect your privacy.": "உங்கள் புகைப்படம் உங்கள் தனிப்பட்ட விர்ச்சுவல் ட்ரை-ஆனிற்கு மட்டுமே பயன்படுத்தப்படுகிறது. நாங்கள் உங்கள் தனியுரிமையை மதிக்கிறோம்.",
