    "What does VERIFIED TODAY mean on coupons?": "کوپن پر \"آج ہی تصدیق شدہ\" (VERIFIED TODAY) کا کیا مطلب ہے؟",
    "How do I create a Price Alert?": "قیمت کا الرٹ (Price Alert) کیسے بنائیں؟",
    "How does AI Virtual Try-On work and are my photos safe?": "AI ورچوئل ٹرائی آن کیسے کام کرتا ہے اور کیا میری تصاویر محفوظ ہیں؟",
    "Does BuyWise charge extra when I buy through Amazon links?": "کیا ایمیزون لنکس کے ذریعے خریدنے پر BuyWise اضافی چارج کرتا ہے؟",
    "What is BuyWise Partners Marketplace?": "BuyWise پارٹنرز مارکیٹ پلیس کیا ہے؟",
    "How do I delete my BuyWise account?": "میں اپنا BuyWise اکاؤنٹ کیسے ڈیلیٹ کروں؟",
    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI ایک AI سے چلنے والا شاپنگ پلیٹ فارم ہے جو \"تلاش کریں → موازنہ کریں → ٹرائی کریں → خریدیں\" پر کام کرتا ہے۔",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare لائیو قیمتوں کو چیک کرتا ہے، بینک ڈسکاؤنٹ کا حساب لگاتا ہے اور حقیقی موثر قیمت دکھاتا ہے۔",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"آج ہی تصدیق شدہ\" کا مطلب ہے کہ کوپن کوڈ آج ہی چیک کیا گیا ہے۔ صرف تصدیق شدہ کوپن ہی شامل ہوتے ہیں۔",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "کسی بھی پروڈکٹ کو تلاش کریں اور \"پرائس الرٹ بنائیں\" پر کلک کریں۔ قیمت کم ہونے پر BuyWise آپ کو مطلع کرے گا۔",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI ورچوئل ٹرائی آن (VTO) آپ کی تصویر پر کپڑے اور جیولری ٹرائی کر کے دکھاتا ہے۔ آپ کی تصاویر محفوظ ہیں۔",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "نہیں۔ ایمیزون یا پارٹنر لنکس سے خریداری پر قیمت بالکل وہی رہتی ہے۔",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise پارٹنرز تصدیق شدہ فروخت کنندگان کو حقیقی مصنوعات (جیسے کانچی پورم سلک ساڑھی اور کندن جیولری) فروخت کرنے کی اجازت دیتا ہے۔",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "آپ پروفائل → اکاؤنٹ ڈیلیٹ کریں سے کسی بھی وقت اپنا اکاؤنٹ ڈیلیٹ کر سکتے ہیں۔ آپ کا تمام ڈیٹا ڈیلیٹ ہو جائے گا۔",
