    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI ಎಂಬುದು \"ಹುಡುಕಿ → ಹೋಲಿಸಿ → ಟ್ರೈ ಮಾಡಿ → ಖರೀದಿಸಿ\" ಮಾದರಿಯಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುವ AI ಶಾಪಿಕಿಂಗ್ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಆಗಿದೆ.",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare ಲೈವ್ ಬೆಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ, ಬ್ಯಾಂಕ್ ರಿಯಾಯಿತಿಗಳನ್ನು ಲೆಕ್ಕಾಚಾರ ಮಾಡುತ್ತದೆ ಮತ್ತು ನಿಜವಾದ ಬೆಲೆಯನ್ನು ತೋರಿಸುತ್ತದೆ.",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"ಇಂದೇ ಪರಿಶೀಲಿಸಲಾಗಿದೆ\" ಎಂದರೆ ಕೂಪನ್ ಕೋಡ್ ಅನ್ನು ಇಂದೇ ಪರಿಶೀಲಿಸಲಾಗಿದೆ. ಮಾನ್ಯ ಕೂಪನ್‌ಗಳನ್ನು ಮಾತ್ರ ರಿಯಾಯಿತಿಗೆ ಸೇರಿಸಲಾಗುತ್ತದೆ.",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "ಯಾವುದೇ ಉತ್ಪನ್ನವನ್ನು ಹುಡುಕಿ ಮತ್ತು \"ಬೆಲೆ ಎಚ್ಚರಿಕೆಯನ್ನು ರಚಿಸಿ\" ಕ್ಲಿಕ್ ಮಾಡಿ. ಬೆಲೆ ಕಡಿಮೆಯಾದಾಗ BuyWise ನಿಮಗೆ ತಿಳಿಸುತ್ತದೆ.",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI ವರ್ಚುವಲ್ ಟ್ರೈ-ಆನ್ (VTO) ನಿಮ್ಮ ಫೋಟೋದಲ್ಲಿ ಉಡುಪುಗಳು ಮತ್ತು ಆಭರಣಗಳನ್ನು ಧರಿಸಿ ನೋಡಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ನಿಮ್ಮ ಫೋಟೋಗಳು ಸುರಕ್ಷಿತವಾಗಿವೆ.",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "ಇಲ್ಲ! ಅಮೆಜಾನ್ ಅಥವಾ ಪಾಲುದಾರ ಲಿಂಕ್‌ಗಳ ಮೂಲಕ ಖರೀದಿಸಿದಾಗ ಬೆಲೆ ಸಂಪೂರ್ಣವಾಗಿ ಒಂದೇ ಆಗಿರುತ್ತದೆ.",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise ಪಾರ್ಟ್‌ನರ್ಸ್ ಪರಿಶೀಲಿಸಿದ ಮಾರಾಟಗಾರರಿಗೆ ನೈಜ ಉತ್ಪನ್ನಗಳನ್ನು (ಕಾಂಜೀವರಂ ರೇಷ್ಮೆ ಸೀರೆಗಳು, ಕುಂದನ್ ಆಭರಣಗಳು) ನೇರವಾಗಿ ಮಾರಾಟ ಮಾಡಲು ಅನುಮತಿಸುತ್ತದೆ.",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "ಪ್ರೊಫೈಲ್ → ಖಾತೆಯನ್ನು ಅಳಿಸಿ ನಿಂದ ನೀವು ಯಾವಾಗ ಬೇಕಾದರೂ ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಅಳಿಸಬಹುದು. ನಿಮ್ಮ ಎಲ್ಲಾ ಡೇಟಾವನ್ನು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸಲಾಗುತ್ತದೆ.",
