    "What is BuyWise AI?": "BuyWise AI എന്നാൽ എന്ത്?",
    "How does SmartCompare work?": "SmartCompare എങ്ങനെ പ്രവർത്തിക്കുന്നു?",
    "What does VERIFIED TODAY mean on coupons?": "കൂപ്പണുകളിൽ \"ഇന്ന് പരിശോധിച്ചത്\" (VERIFIED TODAY) എന്നാൽ എന്താണ്?",
    "How do I create a Price Alert?": "വില മുന്നറിയിപ്പ് (Price Alert) എങ്ങനെ ഉണ്ടാക്കാം?",
    "How does AI Virtual Try-On work and are my photos safe?": "AI വെർച്വൽ ട്രൈ-ഓൺ എങ്ങനെ പ്രവർത്തിക്കുന്നു, എന്റെ ഫോട്ടോകൾ സുരക്ഷിതമാണോ?",
    "Does BuyWise charge extra when I buy through Amazon links?": "ആമസോൺ ലിങ്കുകൾ വഴി വാങ്ങുമ്പോൾ BuyWise അധിക നിരക്ക് ഈടാക്കുമോ?",
    "What is BuyWise Partners Marketplace?": "BuyWise പാർട്ണേഴ്‌സ് മാർക്കറ്റ്‌പ്ലേസ് എന്നാൽ എന്താണ്?",
    "How do I delete my BuyWise account?": "എന്റെ BuyWise അക്കൗണ്ട് എങ്ങനെ ഡിലീറ്റ് ചെയ്യാം?",
    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI എന്നത് \"തിരയുക → താരതമ്യം ചെയ്യുക → ട്രൈ ചെയ്യുക → വാങ്ങുക\" എന്ന മാതൃകയിൽ പ്രവർത്തിക്കുന്ന ഒരു AI ഷാപ്പിംഗ് പ്ലാറ്റ്‌ഫോമാണ്.",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare തത്സമയ വിലകൾ പരിശോധിക്കുകയും ബാങ്ക് ഡിസ്‌കൗണ്ടുകൾ കണക്കാക്കി യഥാർത്ഥ വില കാണിക്കുകയും ചെയ്യുന്നു.",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"ഇന്ന് പരിശോധിച്ചത്\" എന്നാൽ കൂപ്പൺ കോഡ് ഇന്ന് പരിശോധിച്ചതാണ് എന്ന് അർത്ഥമാക്കുന്നു. സാധുവായ കൂപ്പണുകൾ മാത്രമേ ചേർക്കൂ.",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "ഏതെങ്കിലും ഉൽപ്പന്നം തിരഞ്ഞ് \"വില മുന്നറിയിപ്പ് ഉണ്ടാക്കുക\" എന്നത് ക്ലിക്ക് ചെയ്യുക. വില കുറയുമ്പോൾ BuyWise നിങ്ങളെ അറിയിക്കും.",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI വെർച്വൽ ട്രൈ-ഓൺ (VTO) നിങ്ങളുടെ ഫോട്ടോയിൽ വസ്ത്രങ്ങളും ആഭരണങ്ങളും ധരിച്ചു നോക്കാൻ സഹായിക്കുന്നു. നിങ്ങളുടെ ഫോട്ടോകൾ സുരക്ഷിതമാണ്.",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "ഇല്ല! ആമസോൺ അല്ലെങ്കിൽ പാർട്ണർ ലിങ്കുകൾ വഴി വാങ്ങുമ്പോൾ വില കൃത്യമായി ഒന്നുതന്നെയായിരിക്കും.",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise പാർട്ണേഴ്‌സ് അംഗീകൃത വിൽപനക്കാർക്ക് യഥാർത്ഥ ഉൽപ്പന്നങ്ങൾ (കാഞ്ചീപുരം സിൽക്ക് സാരികൾ, കുന്ദൻ ആഭരണങ്ങൾ) നേരിട്ട് വിൽക്കാൻ അനുമതി നൽകുന്നു.",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "പ്രൊഫൈൽ → അക്കൗണ്ട് ഡിലീറ്റ് ചെയ്യുക എന്നതിൽ നിന്ന് നിങ്ങൾക്ക് എപ്പോൾ വേണമെങ്കിലും അക്കൗണ്ട് നീക്കം ചെയ്യാം. നിങ്ങളുടെ വിവരങ്ങൾ നീക്കം ചെയ്യപ്പെടും.",
