    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI ਇੱਕ AI-ਸੰਚਾਲਿਤ ਸ਼ਾਪਿੰਗ ਪਲੇਟਫਾਰਮ ਹੈ ਜੋ \"ਖੋਜੋ → ਤੁਲਨਾ ਕਰੋ → ਟਰਾਈ ਕਰੋ → ਖਰੀਦੋ\" 'ਤੇ ਕੰਮ ਕਰਦਾ ਹੈ।",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare ਲਾਈਵ ਕੀਮਤਾਂ ਦੀ ਜਾਂਚ ਕਰਦਾ ਹੈ, ਬੈਂਕ ਛੋਟਾਂ ਦੀ ਗਣਨਾ ਕਰਦਾ ਹੈ ਅਤੇ ਅਸਲ ਪ੍ਰਭਾਵਸ਼ਾਲੀ ਕੀਮਤ ਦਿਖਾਉਂਦਾ ਹੈ।",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"ਅੱਜ ਹੀ ਤਸਦੀਕ ਕੀਤਾ\" ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਕੂਪਨ ਕੋਡ ਅੱਜ ਹੀ ਚੈੱਕ ਕੀਤਾ ਗਿਆ ਹੈ। ਸਿਰਫ਼ ਵੈਧ ਕੂਪਨ ਹੀ ਛੋਟ ਵਿੱਚ ਸ਼ਾਮਲ ਹੁੰਦੇ ਹਨ।",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "ਕਿਸੇ ਵੀ ਉਤਪਾਦ ਨੂੰ ਖੋਜੋ ਅਤੇ \"ਕੀਮਤ ਅਲਰਟ ਬਣਾਓ\" 'ਤੇ ਕਲਿੱਕ ਕਰੋ। ਕੀਮਤ ਘਟਣ 'ਤੇ BuyWise ਤੁਹਾਨੂੰ ਤੁਰੰਤ ਸੂਚਿਤ ਕਰੇਗਾ।",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI ਵਰਚੁਅਲ ਟਰਾਈ-ਆਨ (VTO) ਤੁਹਾਡੀ ਫੋਟੋ 'ਤੇ ਕੱਪੜੇ ਅਤੇ ਗਹਿਣੇ ਟਰਾਈ ਕਰਕੇ ਦਿਖਾਉਂਦਾ ਹੈ। ਤੁਹਾਡੀਆਂ ਫੋਟੋਆਂ ਸੁਰੱਖਿਅਤ ਹਨ।",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "ਨਹੀਂ! ਅਮੇਜ਼ਨ ਜਾਂ ਪਾਰਟਨਰ ਲਿੰਕਾਂ ਤੋਂ ਖਰੀਦਣ 'ਤੇ ਕੀਮਤ ਬਿਲਕੁਲ ਉਹੀ ਰਹਿੰਦੀ ਹੈ।",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise ਪਾਰਟਨਰਜ਼ ਪ੍ਰਮਾਣਿਤ ਵਿਕਰੇਤਾਵਾਂ ਨੂੰ ਅਸਲ ਉਤਪਾਦ (ਜਿਵੇਂ ਕਾਂਜੀਵਰਮ ਸਿਲਕ ਸਾੜੀਆਂ, ਕੁੰਦਨ ਗਹਿਣੇ) ਸੀਧਾ ਵੇਚਣ ਦੀ ਇਜਾਜ਼ਤ ਦਿੰਦਾ ਹੈ।",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "ਤੁਸੀਂ ਪ੍ਰੋਫਾਈਲ → ਅਕਾਊਂਟ ਡਿਲੀਟ ਕਰੋ ਤੋਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਆਪਣਾ ਅਕਾਊਂਟ ਡਿਲੀਟ ਕਰ ਸਕਦੇ ਹੋ। ਤੁਹਾਡਾ ਸਾਰਾ ਡਾਟਾ ਹਟਾ ਦਿੱਤਾ ਜਾਵੇਗਾ।",
