    "BuyWise AI is an AI-powered shopping intelligence platform operating on \"Search → Compare → Try → Buy\". It compares live prices across Amazon India, Flipkart, Myntra, Nykaa, and AJIO, tracks price drops, verifies coupons, and provides AI Virtual Try-On.": "BuyWise AI হ'ল \"সন্ধান কৰক → তুলনা কৰক → ট্ৰাই কৰক → ক্ৰয় কৰক\" আৰ্হিত চালিত এটা AI শ্বপিং প্লেটফৰ্ম।",
    "SmartCompare queries live merchant pricing, calculates instant bank/credit card discounts, and factors in verified coupons to calculate the true Effective Price for exact product SKUs.": "SmartCompare এ লাইভ মূল্যসমূহ পৰীক্ষা কৰে, বেংক ৰেহাই গণনা কৰে আৰু প্ৰকৃত ফলপ্ৰসূ মূল্য দেখুৱায়।",
    "VERIFIED TODAY means the coupon code was verified against active merchant data or partner vouchers today. Only VERIFIED TODAY active coupons are deducted from effective price calculations.": "\"আজিয়েই সত্যাাপিত\"ৰ অৰ্থ হ'ল কুপন ক'ডটো আজিয়েই পৰীক্ষা কৰা হৈছে। কেৱল বৈধ কুপনহে ৰেহাইত যোগ কৰা হয়।",
    "Search for any product or view its comparison card, then click \"Create Price Alert\". Specify your target price or percentage drop, and BuyWise will notify you when a price drop is detected.": "যিকোনো সামগ্ৰী বিচাৰক আৰু \"মূল্য সতৰ্কবাৰ্তা সৃষ্টি কৰক\"ত ক্লিক কৰক। মূল্য হ্ৰাস পালে BuyWise এ আপোনাক জনাব।",
    "AI Virtual Try-On (VTO) uses high-resolution pose estimation and garment transfer algorithms to preview clothes and jewellery on your uploaded photo. Your photos are private, encrypted, owned by you, and never used for public AI training.": "AI ভাৰ্চুৱেল ট্ৰাই-অন (VTO) এ আপোনাৰ ফটোত কাপোৰ আৰু গহনা ট্ৰাই কৰি চোৱাত সহায় কৰে। আপোনাৰ ফটোসমূহ সম্পূৰ্ণ সুৰক্ষিত।",
    "No! Purchases made through Amazon India or affiliate retailer links cost the exact same price (or lower with verified bank discounts). BuyWise may earn an affiliate commission from qualifying purchases.": "নহয়! আমাজন বা পাৰ্টনাৰ লিংকৰ জৰিয়তে ক্ৰয় কৰিলে মূল্য একেই থাকে।",
    "BuyWise Partners allows verified independent merchants, artisan brands, and local sellers to list authentic products (such as Kanjivaram silk sarees and Kundan jewellery) directly for checkout on BuyWise.": "BuyWise পাৰ্টনাৰ্ছে সত্যাাপিত বিক্ৰেতাসকলক প্ৰকৃত সামগ্ৰী (যেনে কাঞ্জীভৰম ছিল্ক শাড়ী, কুন্দনেৰ গহনা) প্ৰত্যক্ষভাৱে বিক্ৰী কৰাৰ অনুমতি দিয়ে।",
    "You can delete your account at any time from Profile → Delete Account. You will be prompted to type DELETE to confirm. Your profile preferences, saved alerts, and VTO photos will be permanently deleted.": "প্ৰফাইল → একাউণ্ট ডিলিট কৰক ৰ পৰা আপুনি যিকোনো সময়তে একাউণ্ট ডিলিট কৰিব পাৰে। আপোনাৰ তথ্যসমূহ স্থায়ীভাৱে মচি পেলোৱਾ হ'ব।",
